// Thứ tự bắt buộc:
// 1. Cấp phát node mới
// 2. newNode->next = head CŨ  (làm trước khi đổi head)
// 3. head = newNode           (mới cập nhật head)
//
// Đảo bước 2 và 3: head đã đổi trước, newNode->next
// sẽ trỏ vào chính newNode -> mất hết phần đuôi DSLK

// C++ (tham chiếu)
void themdau(node *&head, int x){
    node *newNode = new node;
    newNode->data = x;
    newNode->next = head;   // 1. trỏ tới head cũ
    head = newNode;         // 2. cập nhật head
}

node* themdau(node *head, int x){
    node *newNode = new node;
    newNode->data = x;
    newNode->next = head;
    head = newNode;
    return head;
}
// gọi: head = themdau(head, x);

void themdau(LIST &l, int x){
    node *newNode = new node;
    newNode->data = x; newNode->next = NULL;
    if(l.head == NULL) l.tail = newNode; // DSLK rỗng
    newNode->next = l.head;
    l.head = newNode;
}
